-- civgraph records database: tables added in migration 0002 (generated by scripts/records/schema.mjs --sql 2).



CREATE TABLE office_cards (
  slug TEXT NOT NULL,
  id TEXT,
  title TEXT,
  title_norm TEXT,
  search_norm TEXT,
  ord INTEGER NOT NULL,
  card TEXT NOT NULL,
  detail TEXT,
  row_hash TEXT NOT NULL,
  row_hash_n INTEGER NOT NULL,
  PRIMARY KEY (slug)
);
CREATE INDEX office_cards_ord ON office_cards(ord);

